Tôi đang cố gắng thêm các khoảng thời gian tùy chỉnh cho WP cron trong một plugin. Nó chạy với thời gian lặp lại mặc định "hourly", "daily". Nó không chạy khi tôi thêm thời gian lặp lại tùy chỉnh của riêng mình cho hàm wp_schedule_event. Tôi muốn thực thi một hàm mỗi X giờ (được xác định bởi người dùng). Cảm ơn. Đây là mã:
<?php
/*
Plugin Name: Test Cron
Description: Plugin to Test Cron Jobs.
Version: 1.00
*/
class WP_TestCron {
function __construct()
{
register_activation_hook(__FILE__, array($this, 'TestCron_cron_activate'));
register_deactivation_hook(__FILE__, array($this, 'TestCron_cron_deactivate'));
add_filter('cron_schedules', array($this, 'TestCron_cron_update_schedules'));
add_action('TestCron_cron_eventOne', array($this, 'TestCron_cron_fct'));
add_action('TestCron_cron_eventTwo', array($this, 'TestCron_cron_fct'));
}
function TestCron_cron_activate()
{
// Run => In Schedule Cronjobs
if (!wp_next_scheduled('TestCron_cron_eventOne')) { wp_schedule_event(time(), 'hourly', 'TestCron_cron_eventOne'); }
// Dont't Run => Not in Schedule Cronjobs
if (!wp_next_scheduled('TestCron_cron_eventTwo')) { wp_schedule_event(time(), 'in_per_minute', 'TestCron_cron_eventTwo'); }
}
function TestCron_cron_deactivate()
{
wp_clear_scheduled_hook('TestCron_cron_eventOne');
wp_clear_scheduled_hook('TestCron_cron_eventTwo');
}
function TestCron_cron_update_schedules()
{
return array(
'fively' => array('interval' => 300, 'display' => 'Once in Five minutes'),
'in_per_minute' => array('interval' => 60, 'display' => 'In every minute'),
'in_per_ten_minute' => array('interval' => 60 * 10, 'display' => 'Once in Ten minutes'),
'three_hourly' => array('interval' => 60 * 60 * 3, 'display' => 'Once in three hours')
);
}
function TestCron_cron_fct()
{
$testCcron_post = array();
$testCcron_post['post_title'] = 'Cron Update - '.date('d/m/y \a\t h:i A');
$testCcron_post['post_content'] = 'WP-Cron job is working!';
$testCcron_post['post_status'] = 'publish';
$testCcron_post['post_author'] = 1;
$testCcron_post['post_category'] = array(1);
wp_insert_post( $testCcron_post );
}
}
if (is_admin()) $wpTC = new WP_TestCron();
?>

Trong blog WordPress của tôi, tôi có các sự kiện mà tôi muốn sắp xếp và lọc theo trường tùy chỉnh. Sắp xếp nên được thực hiện bằng trường tùy chỉnh "event_date_end" có nghĩa là mọi sự kiện vẫn đang diễn ra nên được hiển thị. Để sắp xếp các sự kiện, tôi sử dụng trường tùy chỉnh thứ hai "event_date_start". Vì vậy một sự kiện bắt đầu vào ngày 10 và kết thúc vào ngày 20 nên được hiển thị cho đến ngày 20 nhưng nên được sắp xếp tiếp theo tất cả các sự kiện bắt đầu vào ngày 10. Tôi sử dụng Thematic làm chủ đề cha và vì vậy tôi sử dụng hàm query_posts() thêm cả hai quy tắc như các tham số. Đây là cách tôi sử dụng nó trong vòng lặp chỉ mục:

function my_index_loop($content) {
    global $query_string;
    query_posts($query_string
    // lọc theo event_date_end
    ."&meta_key=event_date_end&meta_compare=>=&meta_value=".date('Y-m-d')
    // sắp xếp theo event_date_start
    ."&meta_key=event_date_start&orderby=meta_value&order=ASC");
}
add_filter('thematic_indexloop', 'my_index_loop');

Bây giờ các bài viết được sắp xếp chính xác, nhưng bộ lọc cũng sẽ được thực hiện trên giá trị "event_date_start". Vì vậy một sự kiện đã bắt đầu hôm qua và vẫn đang diễn ra, sẽ không được hiển thị. Nếu tôi chuyển đổi thứ tự của các phần "lọc" và "sắp xếp", tôi sẽ thấy tất cả các sự kiện, nhưng một sự kiện bắt đầu vào ngày 10 và kết thúc vào ngày 20 sẽ được đặt để tất cả các sự kiện vào ngày 20. Tôi biết tôi có thể tạo các truy vấn SQL của riêng mình, nhưng chúng có hoạt động với Thematic không? Và tôi phải viết các câu lệnh như thế nào cho danh sách lưu trữ, danh mục, thẻ?

**Giải pháp**: Sau khi đọc các trang được đề cập, tôi tìm thấy giải pháp sau. Tôi phải sử dụng một số SQL thô và thêm chúng thông qua bộ lọc trong vòng lặp cụ thể. Đây là các hàm mà tôi đã thêm:

function my_loop_where($where){
    global $wpdb;
    $where .= " AND pm_where.meta_value >= '".date('Y-m-d')."'";
    return $where;
}

function my_loop_join($join){
    global $wpdb;
    $join .= " LEFT JOIN " . $wpdb->postmeta . " AS pm_order ON (" . $wpdb->posts . ".ID = pm_order.post_id AND pm_order.meta_key = 'event_date_start')";
    $join .= " LEFT JOIN " . $wpdb->postmeta . " AS pm_where ON (" . $wpdb->posts . ".ID = pm_where.post_id AND pm_where.meta_key = 'event_date_end')";
    return $join;
}

function my_loop_order(){
    return 'pm_order.meta_value ASC';
}

Và sau đó tôi đơn giản chỉ cần thêm bộ lọc cho các hàm này trong vòng lặp chỉ mục ví dụ:

function my_index_loop($content) {
    global $query_string;
    add_filter('posts_where', 'my_loop_where' );
    add_filter('posts_join', 'my_loop_join' );
    add_filter('posts_orderby', 'my_loop_order' );
    query_posts($query_string . "&meta_key=event_date_end&meta_compare=>=&meta_value=".date('Y-m-d')/*."&meta_key=event_date_start&orderby=meta_value&order=ASC"*/);
}
add_filter('thematic_indexloop', 'my_index_loop');

Bây giờ tôi có thể dễ dàng sử dụng bộ lọc và sắp xếp đó trên vòng lặp chỉ mục và danh mục nhưng giữ lại bộ lọc "phong cách nhật ký" mặc định và sắp xếp trên các trang lưu trữ.

Vậy mọi thứ đều hoạt động tốt ngoại trừ việc xác thực. Các thông báo lỗi không hiển thị khi biểu mẫu được gửi trống và bạn vẫn có thể gửi biểu mẫu khi trống. Tôi chắc chắn là tôi đã bỏ lỡ điều gì đó thật rõ ràng. Tôi đã dành vài tiếng để lục lọi trên mạng và đã thử một số cách sửa chữa mà không hiệu quả. Tôi rất mong nhận được sự giúp đỡ.

