Tôi viết một plugin đơn giản sẽ chuyển hướng người dùng đến một trang vào một ngày nhất định. (trong trường hợp này là cho Blackout chống lại SOPA ở Mỹ) Hiện tại tôi đang sử dụng dòng `wp_redirect(plugins_url('simple-sopa-blackout/blackout.php'),302);` để chuyển hướng người dùng vào ngày đã cho. Vấn đề là nó tạo ra một URL xấu như `http://example.net/wp-content/plugins/simple-blackout/blackout.php` Sẽ thật tuyệt nếu chỉ làm cho nó thành `http://example.net/blackout` Tôi đã thử cái mà tôi nghĩ là Codex đúng với đoạn mã sau:

add_filter('rewrite_rules_array','my_insert_rewrite_rules');
add_action('wp_loaded','my_flush_rules');
// flush_rules() nếu các quy tắc của chúng tôi chưa được bao gồm
function my_flush_rules(){
$rules = get_option('rewrite_rules');
if (!isset($rules['blackout/?$'])) {
global $wp_rewrite;
$wp_rewrite->flush_rules();
}
}

// Thêm một quy tắc mới
function my_insert_rewrite_rules($rules){
$newrules = array();
$newrules['blackout/?$'] = plugins_url('simple-sopa-blackout/blackout.php');
return $newrules + $rules;
}

Bất kỳ sự giúp đỡ nào cũng rất tuyệt, nguồn đầy đủ ở đây

SỬA ĐỔI: Đây là những gì tôi có bây giờ, nó hoạt động nếu truy cập trang với các biến truy vấn 'index.php?blackout=stop-sopa' nhưng không nếu tôi đi đến 'blackout/stop-sopa' nó cũng dường như tạo ra một vòng lặp và hết thời gian nếu ngày là đúng

//tạo quy tắc viết lại của bạn
add_action('init', 'wpse38978_init');
function wpse38978_init() {
add_rewrite_rule('blackout/(\d*)$', 'index.php?blackout=$matches[1]', 'top');
}

// thêm blackout vào danh sách trắng của các biến mà wordpress biết và cho phép
function my_plugin_query_vars($query_vars) {
$query_vars[] = 'blackout';
return $query_vars;
}
add_filter('query_vars', 'my_plugin_query_vars');

function my_plugin_parse_request($wp) {
if (array_key_exists('blackout', $wp->query_vars) && $wp->query_vars['blackout'] == 'stop-sopa') {
include(dirname(__FILE__).'/blackout.php');
exit();
}
}
add_action('parse_request', 'my_plugin_parse_request');

if(!function_exists('wp_redirect')) {
require(ABSPATH . WPINC . '/pluggable.php');
}

$current_time = current_time('mysql', '0'); //lấy thời gian blog hiện tại
$ts = strtotime($current_time); //phân tích thời gian blog SQL thành một định dạng có thể sử dụng trong PHP
$check_date = date('m/d/Y', $ts); //đặt ngày vào một định dạng mà chúng ta có thể kiểm tra
$check_hour = date('H', $ts); //đặt ngày vào một định dạng mà chúng ta có thể kiểm tra
$blackout_day = "01/15/2012"; //nên tắt trang web không?
$blackout_day_time_start = "08"; //khi nào chúng ta nên bắt đầu (giờ theo định dạng 24 giờ)
$blackout_day_time_end = "20"; //nên tắt trang web không?

if((!is_admin()) && ($check_date == $blackout_day && ($check_hour >= $blackout_day_time_start || $check_hour < $blackout_day_time_end))){
wp_redirect(get_bloginfo('url').'/blackout/stop-sopa',302);
exit();
}

Tôi đã tạo một loại bài viết tùy chỉnh có tên là "product" và gán một vai trò mới "manager" cho nó. Mọi thứ hoạt động tốt, ngoại trừ trình tải tập tin đa phương tiện cho "product". Tôi thậm chí có thể tải ảnh trực tiếp trong phần "Thêm phương tiện" mà không gặp lỗi nào cả. Vì vậy, tôi bắt đầu kiểm tra với vai trò mặc định "author", và vẫn gặp cùng một lỗi! Thật đáng ngạc nhiên là "author" có thể tải hình ảnh thành công, khi chúng được đặt trong bài viết mặc định, chứ không phải trong "product"! Lời nhắn lỗi nói: **Đã xảy ra lỗi khi tải lên. Hãy thử lại sau.** Dưới đây là mã cho loại bài viết tùy chỉnh:

```php
