Sử dụng mã dưới đây để thay đổi URL trang tác giả thành "nickname". Nó hoạt động tốt nhưng khi biệt danh có nhiều từ thì không thân thiện với URL. Làm thế nào để thực hiện điều này?
add_filter( 'request', 'wpse5742_request' );
function wpse5742_request( $query_vars ) {
  if ( array_key_exists( 'author_name', $query_vars ) ) {
    global $wpdb;
    $author_id = $wpdb->get_var( $wpdb->prepare( "SELECT user_id FROM {$wpdb->usermeta} WHERE meta_key='nickname' AND meta_value = %s", $query_vars['author_name'] ) );
    if ( $author_id ) {
      $query_vars['author'] = $author_id;
      unset( $query_vars['author_name'] );
    }
  }
  return $query_vars;
}
add_filter( 'author_link', 'wpse5742_author_link', 10, 3 );
function wpse5742_author_link( $link, $author_id, $author_nicename ) {
  $author_nickname = get_user_meta( $author_id, 'nickname', true );
  if ( $author_nickname ) {
    $link = str_replace( $author_nicename, $author_nickname, $link );
  }
  return $link;
}
add_action( 'user_profile_update_errors', 'wpse5742_set_user_nicename_to_nickname', 10, 3 );
function wpse5742_set_user_nicename_to_nickname( &$errors, $update, &$user ) {
  if ( ! empty( $user->nickname ) ) {
    $user->user_nicename = sanitize_title( $user->nickname, $user->display_name );
  }
}

Tôi đang sử dụng một hàm để tìm kiếm `post_meta` mà tôi lưu trữ với mỗi bài đăng, nhưng vấn đề là khi tôi tìm kiếm `title`, `tags`, nội dung thì tìm kiếm không hoạt động. Tôi nghĩ hàm mới của tôi chỉ ghi đè lên tính năng tìm kiếm mặc định của WordPress. Đây là mã của tôi:

function custom_search_query( $query ) {
    $custom_fields = array(
        // put all the meta fields you want to search for here
        "post_state",
        "post_region",
        "post_country"
    );
    $searchterm = $query->query_vars['s'];
    // we have to remove the "s" parameter from the query, because it will prevent the posts from being found
    $query->query_vars['s'] = "";
    if ($searchterm != "") {
        $meta_query = array('relation' => 'OR');
        foreach($custom_fields as $cf) {
            array_push($meta_query, array(
                'key' => $cf,
                'value' => $searchterm,
                'compare' => 'LIKE'
            ));
        }
        $query->set("meta_query", $meta_query);
    }
}
add_filter( "pre_get_posts", "custom_search_query");

Vậy tôi đã sai ở đâu? Bạn có ý tưởng nào về cách tôi có thể tìm kiếm mọi thứ không? `post_meta`, `title`, `tags`, `categories`, `content`.

