chức năng get_by_year($sql, $args) {
toàn cầu $wpdb;
trả về $sql .= $wpdb->prepare("VÀ NĂM (`post_date`) = '%s'", $args['năm']); // sửa câu truy vấn SQL dựa trên năm
}

chức năng osu_ym_archive() {
$archiveString = wp_get_archives('type=yearly&echo=0');

// Tìm chuỗi để khớp
preg_match_all("#title='(\d{4})'#", $archiveString, $matches);

foreach ($matches[1] as $năm):
echo "<h3>" . $năm . "</h3>";
add_filter('getarchives_where', "get_by_year" , 666, 2);

// Thiết lập đối số cho wp_get_archives() mới
$args = array(
'type' => 'monthly',
'echo' => 0,
'before' => '<span class="cs-color">• </span>',
'show_post_count' => 1,
'năm' => $năm
);

$monthlyArchives = preg_replace('#(.+)(\s\d{4})(</.+>)#', "$1 $3", wp_get_archives($args));

// Thêm span với lớp vào số bài viết
$monthlyArchives = str_replace( '(', '(<span class="cs-color">', $monthlyArchives );
$monthlyArchives = str_replace( ')', '</span>)', $monthlyArchives );

// In ra lịch sử hàng tháng
