Tôi đang mở rộng chức năng tìm kiếm bằng cách thêm các biến truy vấn tùy chỉnh vào đối tượng truy vấn tìm kiếm thông qua `pre_get_posts` để nó có thể bao gồm tax_query và meta_query như là điều kiện tìm kiếm. Mọi thứ hoạt động tốt ngoại trừ khi biến truy vấn `s` trống, Wordpress chuyển hướng đến trang lưu trữ mà không phải là lý tưởng vì tôi vẫn muốn nó tìm kiếm bài viết dựa trên các biến truy vấn khác (tax_query & meta_query). Tôi nghĩ có thể nó liên quan đến việc thiết lập `is_search` boolean. Vì vậy, tôi đã thử đặt nó thành `true` một cách thủ công nhưng nó bị ghi đè và quay lại `false`. Có cách nào để ép nó luôn ở trạng thái `true` và do đó Wordpress vẫn ở trên trang tìm kiếm ngay cả khi biến truy vấn `s` trống không? Hoặc tôi đang làm sai điều gì đó? Đây là lớp của tôi cho vấn đề này:

class Custom_Query {
private $_get;
private static $_instance;

public function __construct() {
$this->_get = $_GET;
add_filter( 'pre_get_posts', array( $this, 'pre_get_posts' ), 9999 );
add_filter( 'wp', array( $this, 'remove_product_query' ) );
}

/**
* Gắn kết với pre_get_posts để thực hiện truy vấn sản phẩm chính
*
* @access public
* @param mixed $q đối tượng truy vấn
* @return void
*/
function pre_get_posts( $q ) {
// Chúng tôi chỉ muốn ảnh hưởng đến truy vấn chính
if ( !$q->is_main_query() || is_admin() )
return;

$meta_query[] = $this->date_meta_query();
$q->set( 'meta_query', $meta_query );

$tax_query[] = $this->category_tax_query();
$q->set( 'tax_query', $tax_query );

$q->set( 'is_search', true );
}

/**
* Trả về truy vấn meta theo ngày
*
* @return array $meta_query
*/
function date_meta_query() {
$meta_query = array();
$compare = '=';
$value = $this->to_date( $this->_get['ptp_date'] );

if ( isset( $this->_get['ptp_date_start'] ) && isset( $this->_get['ptp_date_end'] ) ) {
$compare = 'BETWEEN';
$value = array( $this->to_date( $this->_get['ptp_date_start'] ), $this->to_date( $this->_get['ptp_date_end'] ) );
}

$meta_query = array(
'key' => '_event_date',
'value' => $value,
'compare' => $compare
);

return $meta_query;
}

/**
* Trả về truy vấn danh mục
*
* @return array $tax_query
*/
function category_tax_query() {
$tax_query = array();
$terms = array( (int) $this->_get['ptp_term_id'] );
$operator = 'IN';

$tax_query = array(
'taxonomy' => 'product_cat',
'field' => 'id',
'terms' => $terms,
'operator' => $operator
);

return $tax_query;
}

/**
* Chuyển đổi chuỗi ngày thành định dạng DATE được hỗ trợ
*
* @param $date
* @return string $date
*/
function to_date( $date ) {
return date( 'Y-m-d H:i:s', strtotime( $date ) );
}

/**
* Xóa truy vấn
*
* @access public
* @return void
*/
function remove_product_query() {
remove_filter( 'pre_get_posts', array( $this, 'pre_get_posts' ) );
}
}

