function mmp_rewrite_rules($rules) {
$newRules = array();
$newRules['products/(.+)/(.+)/(.+)/?$'] = 'index.php?products=$matches[3]'; // cấu trúc tùy chỉnh của tôi sẽ luôn có tên bài viết là phân đoạn URI thứ 5
$newRules['products/(.+)/?$'] = 'index.php?product-descriptions=$matches[1]';

return array_merge($newRules, $rules);
}

function filter_post_type_link($link, $post) {
if ($post->post_type != 'products') {
$link = str_replace('%product_description%', '', $link);
return $link;
}

if ($cats = get_the_terms($post->ID, 'product-descriptions')) {
foreach($cats as $cat){
$slug .= $cat->slug . '/';
}
$link = str_replace('%product_description%', substr($slug, 0, -1), $link); // xem hàm tùy chỉnh được định nghĩa bên dưới
}

return $link;
}

add_filter('post_type_link', 'filter_post_type_link', 10, 2);

