Vì một lý do nào đó tôi không thể tìm ra bất kỳ giải pháp tốt nào để tạo liên kết hình ảnh bài viết. Tôi đã tìm thấy một đoạn mã trên http://wpguy.com/plugins/linked-image/ mà hoạt động, nhưng không xóa đi liên kết cũ, thay vào đó nó bao bọc cả liên kết cũ và hình ảnh trong một thẻ a mới. Điều tôi muốn là cho liên kết cũ bị xóa đi để hình ảnh chỉ được bao bọc trong một thẻ a. Đây là đoạn mã tôi hiện đang sử dụng:

function wpguy_linked_image($content){
  $searchfor = '/(<img[^>]*\/>)/';
  $replacewith = '<a href="'.get_permalink().'">$1</a>';
  if (is_single() === FALSE){
    $content = preg_replace($searchfor, $replacewith, $content, 1);
  }
  return $content;
}
add_filter('the_content', 'wpguy_linked_image');

