Liệu có thể chỉnh sửa truy vấn chính trên trang bằng bộ lọc `pre_get_posts` không? Tôi đã thử nhưng dường như nó không hoạt động.

function pre_wp_queries( $query ) {
    // chỉ kích hoạt trên truy vấn chính
    if ( !$query->is_main_query() )
        return;

    if ( is_page_template('TEMPLATE_NAME.php') ) {
        $query->query_vars['pagename'] = null;
        $query->query_vars['post_type'] = 'post';
        $query->query_vars['posts_per_page'] = 3;
        $query->query_vars['cat'] = 13;
    }
}

add_action('pre_get_posts', 'pre_wp_queries', 9001);

Trên header.php tôi sử dụng dòng này để kiểm tra xem nó có hoạt động không:

var_dump($GLOBALS['wp_query']->request);

