Đây là mã tôi đang sử dụng để tạo một bảng tùy chỉnh có tên là "prefix" + zillow --> trong đó prefix là tiền tố bảng wp cho trang web.

register_activation_hook(__FILE__,'CreateTable');

Hàm thực tế được cung cấp bên dưới - nó kiểm tra xem bảng như vậy đã tồn tại cùng với số phiên bản được gán cho bảng đó (để tôi có thể cập nhật / thay đổi bảng đó trong phiên bản sau của chủ đề) -

function CreateTable() {
//Phiên bản bảng cơ sở dữ liệu
$zillow_db_table_version = "1.0";
$table_name = $wpdb->prefix . "zillow";
$installed_ver = get_option( "zillow_db_table_version" );

//Kiểm tra xem bảng có tồn tại và nếu bảng được cập nhật, nếu không tạo nó
if($wpdb->get_var("SHOW TABLES LIKE '$table_name'") != $table_name || $installed_ver != $zillow_db_table_version ) {
$sql = "CREATE TABLE " . $table_name .
" (propertyid varchar(20) NOT NULL ,
inserted_on date,
UNIQUE KEY id (id) );";
require_once(ABSPATH . 'wp-admin/includes/upgrade.php');
dbDelta($sql);
update_option( "zillow_db_table_version", $zillow_db_table_version );
}

//Thêm phiên bản bảng cơ sở dữ liệu vào các tùy chọn
add_option("zillow_db_table_version", $zillow_db_table_version);
}

Tuy nhiên, bảng không được tạo ra chút nào. Có vấn đề gì với mã trên? Tôi đã thử kích hoạt chủ đề bằng mã trên nhiều lần (sau khi kích hoạt trước một chủ đề khác và sau đó kích hoạt chủ đề này) nhưng không có bảng nào được tạo ra (tôi kiểm tra trực tiếp trong danh sách bảng WP).

Tôi muốn viết một plugin, không phải một theme. Tôi cần có thể chạy một câu lệnh SQL tùy chỉnh và thiết lập kết quả làm bài viết cho vòng lặp. Tôi đang viết một plugin, vì vậy tôi không thể sử dụng các thẻ mẫu hay vòng lặp foreach. Tôi chỉ muốn chạy câu lệnh SQL của mình, chọn đúng hàng và nói với WordPress rằng đây là bài viết cho vòng lặp. Cho đến nay tôi đã thử như sau:

add_filter('pre_get_posts', 'customQuery');

function customQuery() {
    global $wpdb;

    $sql = "câu lệnh SQL ở đây";
    $safequery = $wpdb->prepare($sql);
    $queryResults = $wpdb->get_results($safequery);
}

Điều này hoạt động tốt để lấy kết quả mong muốn. Biến $queryResults chứa dữ liệu chính xác. Sau dòng đó, tôi đã thử một vài điều khác nhau mà không thành công.

...

global $post;
$post = $queryResults[0]; //vì nó là một mảng và tôi chỉ cần kết quả đầu tiên

Điều này không hoạt động. Hoặc nói cách khác, nếu tôi kiểm tra biến $post ngay sau dòng đó, nó sẽ hiển thị kết quả mong muốn, nhưng dường như nó bị đặt lại ở đâu đó phía dưới bởi vì trang hiển thị 404 khi thực sự hiển thị. Tôi cũng đã thử:

...

global $post;
$post = $queryResults[0];
setup_postdata($post);

Kết quả tương tự. Nếu tôi kiểm tra giá trị biến ngay lập tức, tôi sẽ thấy giá trị mong muốn. Với ví dụ thứ hai, tôi thậm chí còn thử chạy một số hàm như the_title(); (mà hoạt động nhưng không giúp ích gì bởi vì tôi đang viết một plugin chứ không phải một theme). Nhưng khi trang được hiển thị, tôi nhận được lỗi 404. Tôi chắc rằng tôi chỉ bỏ lỡ điều đơn giản nào đó mà sẽ cho phép tôi chuyển kết quả của mình vào vòng lặp từ plugin. Các bạn có ý tưởng nào không? Cảm ơn.

Tôi đang thêm các liên kết đăng nhập/đăng xuất vào menu điều hướng bằng mã sau:

function rp_add_login_logout_links( $items, $args ) {
  $link = wp_loginout( get_permalink( get_option( 'woocommerce_myaccount_page_id' ) ), false );

  if ( 'Shop Menu' == $args->menu ) {
    $items .= '<li id="menu-item-login" class="menu-item menu-item-login">' . $link . '</li>';
  }

  return $items;
}

add_filter( 'wp_nav_menu_items', 'rp_add_login_logout_links', 10, 2 );

Vì $items là một chuỗi, tôi chỉ có thể dễ dàng chèn hoặc thêm các liên kết vào danh sách. Tôi cần liên kết này xuất hiện trước một mục menu cụ thể trong danh sách, nó sẽ trở thành mục thứ ba từ cuối cùng. Có bộ lọc hoặc phương pháp nào khác mà tôi có thể sử dụng để thực hiện điều này? Tôi đã thử sử dụng strpos để tìm mục điều hướng tôi đang tìm kiếm và thao tác với chuỗi $items nhưng không thể khớp với mục menu HTML.

Tôi đang cố gắng liệt kê các bài viết từ một danh mục duy nhất trong hệ thống phân loại tùy chỉnh của tôi. Tôi đã tạo một loại bài viết tùy chỉnh được gọi là "Inventory" và một hệ thống phân loại tùy chỉnh được gọi là "Inventory Category". Sau đó, tôi tạo một số danh mục sử dụng hệ thống phân loại "Inventory Category". Tôi muốn hiển thị các bài viết chỉ từ một danh mục duy nhất. Để làm điều này, tôi sử dụng hàm query_posts() với các tham số sau:

query_posts( array( 'post_type' => 'inventory', 'inventory-category' => 'bulk-racks' ) );

Tuy nhiên, mã này trả về tất cả các bài viết trong hệ thống phân loại "Inventory Category" thay vì chỉ những bài viết trong danh mục "bulk racks". Ai có thể giúp tôi sửa lỗi này không? Đây là cách tôi tạo loại bài viết và hệ thống phân loại tùy chỉnh:

/* --- Tạo loại bài viết Inventory --- */
add_action('init', 'inventory_register');
function inventory_register() {
    $args = array(
        'label' => __('Inventory'),
        'singular_label' => __('Inventory'),
        'public' => true,
