}

/* --- Đăng ký hệ thống phân loại tùy chỉnh cho danh sách Inventory --- */
add_action( 'init', 'register_my_taxonomies', 0 );
function register_my_taxonomies() {
    register_taxonomy(
        'division',
        array( 'inventory' ),
        array(
            'hierarchical' => true,
            'public' => true,
            'labels' => array(
                'name' => __( 'Inventory Category' ),
                'singular_name' => __( 'Inventory Categories' ),
                'show_ui' => true,
                'show_in_nav_menus' => true,
            ),
        )
    );
}

Tôi cứ nhìn thấy mẫu này, và thắc mắc nó dùng để làm gì, và WP sử dụng nó như thế nào bên trong:
if ( empty($post) ) {
    if ( isset($GLOBALS['post']) )
        $_post = & $GLOBALS['post'];
    else
        return $null;
} elseif ( is_object($post) && empty($post->filter) ) {
    _get_post_ancestors($post);
    $_post = sanitize_post($post, 'raw');
    wp_cache_add($post->ID, $_post, 'posts');
} else {
    if ( is_object($post) )
        $post_id = $post->ID;
    else
        $post_id = $post;
Dòng cụ thể cần quan tâm là `is_object($post) && empty($post->filter)`. Tôi đã thấy thuộc tính `filter` này được liên kết với các đối tượng khác. Thắc mắc nó làm gì và làm thế nào có thể sử dụng?
