Tôi có một loại bài viết tùy chỉnh mà tôi đang cố gắng liệt kê sử dụng một WP_Query mới. Nó hoạt động tốt khi tôi thêm mã ngắn trong nội dung bài viết chính. Tuy nhiên, khi tôi thêm mã ngắn vào một trường tùy chỉnh (mà tôi đã đặt để hiển thị trên trang cùng với nội dung chính như một "cột" thứ hai), nội dung chính biến mất! Nếu tôi bình luận ra các dòng "while... have_posts()" và "endwhile", nội dung chính được hiển thị; tuy nhiên, ngay cả sau khi bình luận ra mọi dòng khác, nội dung chính biến mất trừ khi tôi cũng bỏ qua "trong khi". Tôi khá chắc chắn nó phải làm việc với việc sử dụng WP_Query (một cách nào đó nó chiếm quyền kiểm soát vòng lặp), mặc dù nó không nên. Có điều gì tôi bỏ lỡ? Đây là mã ngắn:

function ia_news_display_test($atts) { // [ia_news cat = 'category' num = 'numbertodisplay']

extract(shortcode_atts(array(

'cat' => 'any',

'num' => '2',

), $atts));

$dirloop = new wp_query(array(

'post_type' => 'ia_news',

'category_name' => $cat,

'posts_per_page' => $num,

'orderby' => 'menu_order',

'order' => 'ASC'

));

if ($dirloop->have_posts()) {

$content = "<ul class='ia_news_list'>\n";

while ( $dirloop->have_posts() ) : $dirloop->the_post();

$custom = get_post_custom($post->ID);

$file_id = $custom["upload_file"][0];

$file_begin = $custom["begin_date"][0];

$file_end = $custom["end_date"][0];

if ('' != $file_end) {$file_end = "to".$file_end;}

$file_url = wp_get_attachment_url($file_id);

if ('' != $file_url) { //Kiểm tra sự tồn tại của URL tệp

$content .= "<li class='ia_nl'><a href='".$file_url."'>".$cat." ".$file_begin.$file_end."</a></li>\n";

}

endwhile;

$content .= "</ul>\n";

} else { $content = "nothing"; }

return $content;

}

