class MY_Widget extends WP_Widget {

    function MY_Widget() {
        $widget_ops = array(
            'classname' => 'example',
            'description' => __('A widget that displays the authors name ', 'example')
        );
        $control_ops = array(
            'width' => 300,
            'height' => 350,
            'id_base' => 'example-widget'
        );
        $this->WP_Widget( 'example-widget', __('Example Widget', 'example'), $widget_ops, $control_ops );
    }

    function widget( $args, $instance ) {
        extract( $args );

        // Các biến từ cài đặt widget
        $title = apply_filters('widget_title', $instance['title'] );
        $name = $instance['name'];
        $show_info = isset( $instance['show_info'] ) ? $instance['show_info'] : false;

        echo $before_widget;

        // Hiển thị tiêu đề widget
        if ( $title ) {
            echo $before_title . $title . $after_title;
        }

        // Hiển thị tên
        if ( $name ) {
            printf( '<p>' . __('Hey their Sailor! My name is %1$s.', 'example') . '</p>', $name );
        }

        if ( $show_info ) {
            printf( $name );
        }

        echo $after_widget;
    }

    // Cập nhật widget
    function update( $new_instance, $old_instance ) {
        $instance = $old_instance;

        // Loại bỏ thẻ HTML khỏi tiêu đề và tên
        $instance['title'] = strip_tags( $new_instance['title'] );
        $instance['name'] = strip_tags( $new_instance['name'] );
        $instance['show_info'] = $new_instance['show_info'];

        return $instance;
    }

    // Hình thức của widget
