*/
function remove_cpt_term($post_ID) {
    $post = get_post($post_ID);
    $term = get_term_by('name', $post->post_name, 'custom_taxonomy', 'ARRAY_A');
    if ($post->post_type == $custom_post_type && $term['count'] == 0)
