class Bootstrap_Walker_Nav_Menu extends Walker_Nav_Menu {
// Các yếu tố <ul>
function start_lvl(&$output, $depth) {
// Dấu cách mã
$indent = ($depth > 0 ? str_repeat("\t", $depth) : '');
// Xây dựng các lớp
$classes = array(
// Chỉ cấp cao nhất sẽ có các menu thả xuống
$depth == 0 ? 'dropdown-menu' : '',
// Gán một lớp cho các mục lồng sâu hơn
$depth >= 1 ? 'sub-menu col-sm-4' : '');
$class_names = implode(' ', $classes);
// Xây dựng HTML - <ul> trở thành <div> ở các cấp cao nhất
if ($depth == 0)
$output .= "\n" . $indent . '<ul class="' . $class_names . '">' . "\n" . $indent . '<li class="col-sm-12">' . "\n";
else
$output .= "\n" . $indent . '<ul class="' . $class_names . '">' . "\n";
}

// Các yếu tố <li> và liên kết <a>
function start_el(&$output, $item, $depth = 0, $args = array(), $id = 0) {
// Dấu cách mã
$indent = ($depth) ? str_repeat("\t", $depth) : '';
// Chuẩn bị
$li_attributes = '';
$class_names = $value = '';
$classes = empty($item -> classes) ? array() : (array)$item -> classes;

// Xây dựng các lớp và thuộc tính cho các yếu tố <li> có các menu lồng nhau
if ($args -> has_children && $depth == 0) {
$classes[] = 'dropdown yamm-fw';
$li_attributes .= 'data-dropdown="dropdown"';
}
$classes[] = 'menu-item-' . $item -> ID;

// Nếu chúng ta đang ở trang hiện tại, thêm lớp hoạt động vào mục menu đó
$classes[] = ($item -> current) ? 'active' : '';

// Thêm tất cả các lớp của Wordpress, bao gồm cả những lớp được người dùng đặt trong Wordpress
$class_names = join(' ', apply_filters('nav_menu_css_class', array_filter($classes), $item, $args));
$class_names = ' class="' . esc_attr($class_names) . '"';

// Thêm id vào các yếu tố <li>
$id = apply_filters('nav_menu_item_id', 'menu-item-' . $item -> ID, $item, $args);
$id = strlen($id) ? ' id="' . esc_attr($id) . '"' : '';

// Xây dựng HTML - các yếu tố <li> ở cấp cao nhất trở thành <div>
if ($depth == 0)
$output .= $indent . '<li class="dropdown">' . "\n" . $indent . '<div ' . $id . $value . $class_names . $li_attributes . '>';

elseif ($depth == 1)
$output .= $indent . '<div class="yamm-content column row">';
else
$output .= $indent . '<li' . $id . $value . $class_names . $li_attributes . '>';

// Xây dựng các thuộc tính và lớp cho các yếu tố liên kết <a>
$attributes = !empty($item -> attr_title) ? ' title="' . esc_attr($item -> attr_title) . '"' : '';
$attributes .= !empty($item -> target) ? ' target="' . esc_attr($item -> target) . '"' : '';
$attributes .= !empty($item -> xfn) ? ' rel="' . esc_attr($item -> xfn) . '"' : '';
$attributes .= !empty($item -> url) ? ' href="' . esc_attr($item -> url) . '"' : '';
$attributes .= ($args -> has_children && $depth == 0) ? ' class="dropdown-toggle" data-toggle="dropdown"' : '';

// Xây dựng HTML cho liên kết <a>
$item_output = $args -> before;
$item_output .= '<a' . $attributes . '>';
$item_output .= $args -> link_before . apply_filters('the_title', $item -> title, $item -> ID) . $args -> link_after;

// Thêm một "caret" của Bootstrap vào các nút chuyển đổi menu thả xuống cấp cao nhất
$item_output .= ($args -> has_children && $depth == 0) ? ' <b class="caret"></b> ' : '';
$item_output .= '</a>';

if ($depth == 0)
$item_output .= '<p class="sub">' . $item -> description . '</p>';
else
'';
$item_output .= $args -> after;

// Đầu ra HTML cuối cùng
$output .= apply_filters('walker_nav_menu_start_el', $item_output, $item, $depth, $args);
}

function end_el(&$output, $item, $depth) {
// Đóng các yếu tố được mở trong start_el
if ($depth == 0)
$output .= '</div>' . "\n" . '</li>' . "\n";
elseif ($depth == 1)
$output .= '</div>' . "\n";
else
$output .= "</li>\n";
}

function end_lvl(&$output, $depth) {
// Dấu cách mã
$indent = ($depth > 0 ? str_repeat("\t", $depth) : '');
// Đóng các yếu tố được mở trong start_lvl
if ($depth == 0)
$output .= $indent . '</li>' . "\n" . $indent . '</ul>' . "\n";
else
$output .= $indent . '</ul>' . "\n";
}

// Vượt qua hàm display_element để thêm thuộc tính has_children @since WP 3.4
function display_element($element, &$children_elements, $max_depth, $depth = 0, $args, &$output) {
if (!$element)
return;
$id_field = $this -> db_fields['id'];

// Hiển thị phần tử này
if (is_array($args[0]))
$args[0]['has_children'] = !empty($children_elements[$element -> $id_field]);
else if (is_object($args[0]))
$args[0] -> has_children = !empty($children_elements[$element -> $id_field]);
$cb_args = array_merge(array(&$output, $element, $depth), $args);
call_user_func_array(array(&$this, 'start_el'), $cb_args);
$id = $element -> $id_field;

// Chỉ di chuyển xuống khi độ sâu là đúng và có các phần tử con cho phần tử này
if (($max_depth == 0 || $max_depth > $depth + 1) && isset($children_elements[$id])) {
foreach ($children_elements[ $id ] as $child) {
if (!isset($newlevel)) {
$newlevel = true;
// Bắt đầu phân cách tử con
$cb_args = array_merge(array(&$output, $depth), $args);
call_user_func_array(array(&$this, 'start_lvl'), $cb_args);
}
$this -> display_element($child, $children_elements, $max_depth, $depth + 1, $args, $output);
}
unset($children_elements[$id]);
}

if (isset($newlevel) && $newlevel) {
// Kết thúc phân cách tử con
$cb_args = array_merge(array(&$output, $depth), $args);
call_user_func_array(array(&$this, 'end_lvl'), $cb_args);
}

// Kết thúc phần tử này
$cb_args = array_merge(array(&$output, $element, $depth), $args);
call_user_func_array(array(&$this, 'end_el'), $cb_args);
}

}

