Tôi đã viết một loạt các hàm trong functions.php của chủ đề để tôi có thể sử dụng mã ngắn để đăng video Vine, ví dụ như [vine id="hx9LlrZxdqV"]. Các hàm của tôi sau đó sẽ lấy URL .mp4 thô và hiển thị nó như một video trên trang bài viết của tôi. Khách hàng cũng muốn tôi thêm tích hợp Facebook để khi bài viết được xuất bản với mã ngắn Vine trong đó, video sẽ được gửi cùng lúc đến Facebook nơi nó được nhúng như một video để người dùng có thể phát nó trên Facebook cũng giống như Vinescope làm. Ngoài ra, tôi cũng cần thêm các bình luận của Facebook vào bài viết WP và có thể cũng nhận được số lượt thích và chia sẻ cho mỗi video/bài viết trên Facebook. Đây là các hàm của tôi để hiển thị Vine trên WordPress:

function vine($id) { // Lấy URL .mp4 thô từ ID Vine $vine = file_get_contents("http://vine.co/v/{$id}"); preg_match('/property="twitter:player:stream" content="(.*?)"/', $vine, $matches); return ($matches[1]) ? $matches[1] : false; }

function vineDesc($id) { $vine = file_get_contents("http://vine.co/v/{$id}"); preg_match('~<\s*meta\s+property="(twitter:description)"\s+content="([^"]*)~i', $vine, $matches); return ($matches[2]) ? $matches[2] : false; }

function vineAuthor($id) { $vine = file_get_contents("http://vine.co/v/{$id}"); preg_match('~<\s*meta\s+property="(twitter:title)"\s+content="([^"]*)~i', $vine, $matches); $authorName = preg_replace('/\'s post on Vine/', '', $matches[2]); return ($authorName) ? $authorName : false; }

function embedVine($atts) { extract(shortcode_atts(array( "id" => '', ), $atts)); $vine_id = $id; $videourl = vine($vine_id); // Gán URL .mp4 thô từ hàm vine() ở trên cho biến $vineDesc = vineDesc($vine_id); $vineAuthor = vineAuthor($vine_id); $output = ""; $output .= "<div class='vine-video'><video class='vine-embed'><source src=". $videourl ." type='video/mp4'></video><div class='video-overlay is-visible'><img src='/wp-content/themes/hot-new-feed/images/vine-logo.png' alt='Vine' class='vine-logo' /><div class='vine-info'><span class='vine-desc'>" . $vineDesc . "</span><a class='vine-author' href='http://vine.co/v/" . $vine_id . "'> by " . $vineAuthor . " &rarr;</a></div></div>" . postShareBtn() . "</div>"; return $output; } add_shortcode("vine", "embedVine"); Tôi sẵn sàng sử dụng Plugin nhưng nếu có thể tôi muốn tránh sử dụng chúng càng nhiều càng tốt. SỬA ĐỔI: Ngoài ra, nếu việc nhúng Vine vào Facebook không thể thực hiện được, thì tôi cũng chấp nhận nếu nó chỉ đăng một liên kết đến Vine để người dùng nhấp vào, và sau đó nhận được các bình luận và có thể là lượt thích/chia sẻ để hiển thị trên trang WordPress. Cảm ơn mọi sự giúp đỡ :)

