function wpPartValidate_settings( $input ) {
    if ( check_admin_referer( 'wpPart_nonce_field', 'wpPart_nonce_verify_adm' ) ) {
        // Tạo mảng để lưu các tùy chọn đã được xác nhận
        $output = array();
        foreach( $input as $key => $value ) {
            // Kiểm tra xem tùy chọn hiện tại có giá trị không, nếu có, xử lý nó.
            if( isset( $input[$key] ) ) {
                // Loại bỏ mọi thẻ HTML và PHP và xử lý chuỗi được trích dẫn đúng cách
                $output[$key] = strip_tags( stripslashes( $input[ $key ] ) );
            }
        }
    }
    // Trả về mảng xử lý bất kỳ hàm bổ sung nào được lọc bởi hành động này
    return apply_filters( 'wpPartValidate_settings', $output, $input );
}

