function myPlugin_activate(){
    if ( get_option( 'myPlugin_activated' ) !== "1"){
        //bỏ qua bất kỳ hàm nào bạn không muốn chạy
        myPlugin_copy('themes');
        myPlugin_copy('plugins');
        myPlugin_images();
        myPlugin_options();
        myPlugin_settings();
        myPlugin_widgets();
        myPlugin_links();
        myPlugin_posts();
        myPlugin_pages();
        myPlugin_custom_menus();
        myPlugin_cleanup();
        clean_term_cache('','category'); //không hoạt động ở đây
        update_option('myPlugin_activated', "1");
    }
}

function myPlugin_cleanup(){
    //bao gồm các phụ thuộc
    require_once(ABSPATH.'/wp-admin/includes/taxonomy.php');
    if(!get_cat_ID('nofollow')){wp_create_category('nofollow',1);}
    if(!get_cat_ID('noindex')){wp_create_category('noindex',1);}
    clean_term_cache('','category'); //cũng không hoạt động ở đây
}

register_activation_hook(__FILE__, 'myPlugin_activate');

