function filter_post_type_link( $link, $post ) {
    if ( $post->post_type != 'work' )
        return $link;

    if ( $cats = get_the_terms( $post->ID, 'work_category' ) )
        $link = str_replace( '%work_category%', array_pop( $cats )->slug, $link );

    return $link;
}

