Trong init.php tôi có một hàm callback để get_userid(). Cho đến nay rất tốt. Trong plugin tôi có một khối để kiểm tra user_id:

public static function get_user_id() {
  // Cache
  static $user_id = FALSE;

  // Mã này chỉ cần được thực thi một lần mỗi yêu cầu
  if ($user_id !== FALSE)
    return $user_id;

  // Callback config được để trống
  if ( ! ThumbsUp::config('user_id_callback'))
    return $user_id = NULL;

  // Tải ID người dùng
  $user_id = (int) call_user_func(ThumbsUp::config('user_id_callback'));

  // trả về giá trị từ get_userid()
  // echo $user_id => 33

  // Đặt ID người dùng thành NULL nếu không tìm thấy
  return ($user_id) ? $user_id : $user_id = NULL;
}

