```php
function display_feed_items() {
    include_once( ABSPATH . WPINC . '/feed.php' );
    $rss = fetch_feed( $_POST['feed'] );
    if ( ! is_wp_error( $rss ) ) :
        $maxitems = $rss->get_item_quantity( 7 );
        $rss_items = $rss->get_items( 0, $maxitems );
    endif;
    if ( $maxitems == 0 ) :
        $feeds = '<li> ' . _e( 'Không có mục nào' ) . '</li>';
    else :
        foreach ( $rss_items as $item ) :
            $feedlink = esc_url( $item->get_permalink() );
            $feedtitle = esc_html( $item->get_title() );
            $feeds = '<li><a rel="nofollow" href="' . $feedlink . '" target="_blank">' . $feedtitle . '</a></li>';
        endforeach;
    endif;
    echo $feeds;
    die();
}
add_action( 'wp_ajax_getfeeddetails', 'display_feed_items' );
add_action( 'wp_ajax_nopriv_getfeeddetails', 'display_feed_items' );
```

