WordPress nonce đang khiến tôi phát điên! Tôi đã gặp vấn đề này khi bắt đầu tạo plugin và đã xóa nó, nhưng bây giờ tôi lại quay trở lại với nó và vẫn không biết phải làm gì. Tôi đã tìm kiếm khắp nơi để tìm một giải pháp. Mã của tôi giống/tương tự như các ví dụ khác. Tôi nhận được lỗi "undefined index 'mrlpt_client_check'". Tôi cũng nhận được cùng lỗi cho 'mrlpt_client' khi kiểm tra quyền dựa trên năng lực người dùng, nhưng đó là kiểu bài viết tùy chỉnh mà tôi đã tạo nên tôi không chắc tại sao nó cũng không hoạt động? Dưới đây là mã nơi có nội dung nonce. Bao gồm chỉ bao gồm một biểu mẫu ngắn với hai trường đầu vào, một cho địa chỉ email và một cho số điện thoại, trong một hộp siêu dữ liệu tùy chỉnh. Tôi đã thử bao gồm wp_nonce_field() cùng với HTML form include, nhưng điều đó cũng không hoạt động, cùng lỗi. Ai có thể giúp được không? Cảm ơn!

function mrlpt_client_details( $client_post ) {
    // Lấy siêu dữ liệu đã lưu nếu tồn tại
    $mrlpt_clientEmail = get_post_meta( $client_post->ID, '_mrlpt_client_email', true );
    $mrlpt_clientPhoneNum = get_post_meta( $client_post->ID, '_mrlpt_client_phone_num', true );

    // Tạo một trường nonce để xác minh
    wp_nonce_field( 'mrlpt_submit_client', 'mrlpt_client_check' );

    // Bao gồm các phần tử biểu mẫu bên trong hộp siêu dữ liệu
    require_once( 'includes/mrlpt-client-form.php' );
}

// Cập nhật/Lưu siêu dữ liệu khách hàng
add_action( 'save_post', 'save_client_metadata' );

function save_client_metadata( $client_post_id ) {
    // Xác minh đây là một quy trình tự động lưu.
    // Nếu nó là quy trình tự động lưu của chúng tôi, biểu mẫu chưa được gửi đi, vì vậy chúng tôi không muốn làm bất cứ điều gì
    if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) {
        return;
    }

    // Xác minh đây là từ màn hình của chúng tôi và với quyền ủy quyền đúng, vì save_post có thể được kích hoạt vào những thời điểm khác
    if ( !isset( $_POST['mrlpt_client_check'] ) && !wp_verify_nonce( $_POST['mrlpt_client_check'], 'mrlpt_submit_client' ) ) {
        return;
    }

    // Kiểm tra quyền - Nếu kiểu bài viết là mrlpt_client
    if ( 'post' == $_POST['mrlpt_client'] ) {
        // Nếu người dùng không thể xuất bản bài viết
        if ( !current_user_can_for_blog( $blog_id, 'publish-post' ) ) {
            // Kiểm tra theo năng lực, không phải vai trò
            wp_die( 'Quyền hạn không đủ: Xin lỗi, bạn không có quyền truy cập vào trang này.' );
        }
    }

    // Được rồi, chúng tôi đã xác thực: chúng tôi cần tìm và lưu dữ liệu
    // Xác minh siêu dữ liệu đã được thiết lập
    if ( isset( $_POST['mrlpt_client_email'] ) && isset( $_POST['mrlpt_client_phone_num'] ) ) {
        // Lưu siêu dữ liệu
        update_post_meta( $client_post_id, '_mrlpt_client_email', strip_tags( $_POST['mrlpt_client_email'] ) );
        update_post_meta( $client_post_id, '_mrlpt_client_phone_num', strip_tags( $_POST['mrlpt_client_phone_num'] ) );
    }
}

Tôi đang gặp vấn đề với việc thêm bộ lọc vào 'post_updated_messages' mà tôi không hiểu đầy đủ. Tôi đã viết một hàm như sau:

function acc_course_updated_messages( $messages ) {
$post = get_post();
$post_type = get_post_type( $post );
$post_type_object = get_post_type_object( $post_type );
$singular = 'Khóa học';
$messages['course'] = array(
0 => '', // Không sử dụng. Các thông điệp bắt đầu từ chỉ số 1.
1 => __( $singular . ' đã được cập nhật.', TEXTDOMAIN ),
2 => __( 'Trường tùy chỉnh đã được cập nhật.', TEXTDOMAIN ),
3 => __( 'Trường tùy chỉnh đã bị xóa.', TEXTDOMAIN ),
4 => __( $singular . ' đã được cập nhật.', TEXTDOMAIN ),
/* translators: %s: ngày và thời gian của bản sửa đổi */
5 => isset( $_GET['revision'] ) ? sprintf( __( $singular . ' đã được khôi phục lại phiên bản từ %s', TEXTDOMAIN ), wp_post_revision_title( (int) $_GET['revision'], false ) ) : false,
6 => __( $singular . ' đã được công khai.', TEXTDOMAIN ),
7 => __( $singular . ' đã được lưu lại.', TEXTDOMAIN ),
8 => __( $singular . ' đã được gửi đi.', TEXTDOMAIN ),
9 => sprintf(
__( $singular . ' đã được lên lịch cho: <strong>%1$s</strong>.', TEXTDOMAIN ),
// translators: Định dạng hộp xuất bản, xem http://php.net/date
date_i18n( __( 'M j, Y @ G:i', TEXTDOMAIN ), strtotime( $post->post_date ) )
),
10 => __( $singular . ' bản nháp đã được cập nhật.', TEXTDOMAIN ),
);
if ( $post_type_object->publicly_queryable ) {
$permalink = get_permalink( $post->ID );
$view_link = sprintf( ' <a href="%s">%s</a>', esc_url( $permalink ), __( 'Xem ' . $singular, TEXTDOMAIN ) );
$messages[ $post_type ][1] .= $view_link;
$messages[ $post_type ][6] .= $view_link;
$messages[ $post_type ][9] .= $view_link;
$preview_permalink = add_query_arg( 'preview', 'true', $permalink );
$preview_link = sprintf( ' <a target="_blank" href="%s">%s</a>', esc_url( $preview_permalink ), __( 'Xem trước ' . $singular, TEXTDOMAIN ) );
$messages[ $post_type ][8] .= $preview_link;
$messages[ $post_type ][10] .= $preview_link;
}
return $messages;
}
add_filter( 'post_updated_messages', 'acc_course_updated_messages' );

Tôi có hai hàm này trong hai tập tin khác nhau - được đặt tên khác nhau. Hầu hết nó hoạt động tốt, ngoại trừ khi chúng tôi đến việc thêm $view_link vào mảng $messages. Nếu tôi gắn với giá trị của $messages[ $post_type ][x], giá trị được nối với giá trị $messages[ $post_type ][x] của bài đăng loại trước đó. Vì vậy, tôi kết thúc với:

Xem Khóa học Xem Hồ sơ

