Tôi đang cố gắng hiển thị một số meta tùy chỉnh trong một lớp Walker_Category mở rộng. Tôi không có nhiều kinh nghiệm với Thiết kế Hướng Đối tượng nên vấn đề này khá khó để tôi giải quyết. Về cơ bản, tôi đang cố gắng kiểm tra các hộp của các danh mục mà người dùng đã nhập nếu họ vô tình chỉnh sửa bài viết với dữ liệu đã lưu. Đây là mã cho đến nay trong lớp mở rộng:

<?php
class MyCategoryWalker extends Walker_Category{
public $post_cb;
// truyền qua các lựa chọn hộp kiểm đã lưu
function __construct($custom_meta){
$this->post_cb = $custom_meta;
}
// nhận mảng các lựa chọn hộp kiểm và chuyển đổi nó thành định dạng chuỗi đơn giản
function get_cat_rp_list(){
$the_cat_list;
foreach($this->post_cb as $cat_list){
$the_cat_list .= $cat_list.', ';
}
$the_cat_list = rtrim($the_cat_list, ',');
return $the_cat_list;
}
// thực sự xây dựng danh sách hộp kiểm
public function start_el(&$output, $term, $depth, $args){
echo self::get_cat_rp_list();
$args = wp_parse_args(array(
'name' => 'my_category_input',
'checked' => array(self::get_cat_rp_list()), // sẽ nhập chuỗi hộp kiểm đã lưu
), $args);
extract($args);
$checked = checked(in_array($term->term_id, $checked));
ob_start(); ?>
<li>
<input type="checkbox" <?php print $checked; ?> id="category-<?php print $term->term_id; ?>" name="<?php print $name; ?>[]" value="<?php print $term->term_id; ?>" />
<label for="category-<?php print $term->term_id; ?>">
<?php print esc_attr($term->name); ?>
</label>
<?php // đóng thẻ LI được thêm vào bên trong end_el
$output .= ob_get_clean();
}
}
Vì vậy đó là lớp của tôi, Để mục đích thử nghiệm, tôi đã thêm "`echo self::get_cat_rp_list();`" trong phương thức `start_el()`. Trong bài viết cụ thể mà tôi có, chỉ có hai danh mục được lưu trữ trong bài viết. Tuy nhiên, nó hiển thị hai danh mục đó khoảng 30 lần (số lượng danh mục tổng thể trên trang web của tôi) đây là mã của tôi để hiển thị danh sách kiểm tra trên bài viết:

$custom_meta = get_post_meta($post->ID, '_custom-meta-box', true);
$newWalker = new MyCategoryWalker();
wp_list_categories(array(
'walker' => $newWalker,
'name' => 'my_category_input',
// tên đầu vào
));
