Tôi có một loại bài viết tùy chỉnh được gọi là "sản phẩm". Nó được phân loại với hai danh mục "product_category" (được ưu tiên hơn) và "product_group". Tôi muốn các liên kết trang đơn cho các sản phẩm xuất hiện như sau: "products/%product_category%/%product_group%/%postname/" và đối với "archives", thực ra là tổng quan về các sản phẩm trong một danh mục sản phẩm như sau: "products/%product_category%/" . Đây là cách tiếp cận của tôi:

add_filter('rewrite_rules_array', 'rewrite_rules');

function rewrite_rules($rules)
{
    $newRules = array();
    $newRules['products/(.+)/(.+)/(.+)/?$'] = 'index.php?product_category=$matches[1]&product_group=$matches[2]&product=$matches[3]';
    $newRules['products/(.+)/(.+)/?$'] = 'index.php?product_category=$matches[1]&product_group=$matches[2]';
    $newRules['products/(.+)/?$'] = 'index.php?product_category=$matches[1]';
    return array_merge($newRules, $rules);
}

