add_action("template_redirect", array($this, "redirection_section"), 11);
function redirection_section() {
    if( is_404() )
        $this->uni_page_redirect();
}
function uni_page_redirect() {
    include_once dirname(__FILE__) . '/uni_links.php';
    $Links = new UNI_Links();
    $slug = ltrim(preg_replace('#/$#', '', urldecode($_SERVER['REQUEST_URI'])), '/');
    if( $Links->is_valid_slug($slug) ) {
        // Khởi tạo với Slug
        do_action("ulr_init_slug", $slug);
        $Links->generate_links($slug);
        exit();
    }
    return false;
}
