    // Debug để kiểm tra các cuộc gọi
    file_put_contents(PLUGIN_BASE . '/debug.txt', "call \r\n", FILE_APPEND);
    $sql = $wpdb->prepare("update {$table_slugs} set stat= stat+1 where slug_name=%s", $slug_name);
    $wpdb->query($sql);
}
