Tôi đang gặp phải vấn đề sau: mặc định WordPress RSS Feed cũng bao gồm cả thẻ trong chức năng danh mục. Kết quả là, nếu bạn sử dụng một thẻ hợp nhất để hiển thị danh mục bài viết (ví dụ: Tôi đang sử dụng chiến dịch RSS trên Mailchimp để gửi email cho người đăng ký) nó hiển thị danh mục và ngoài ra tất cả các thẻ. Tôi đã tìm kiếm và tìm thấy tệp '/wp-includes/feed.php' ở dòng #301 có mã liên quan. Tôi cũng đính kèm nó ở đây:

function get_the_category_rss($type = null) {
    if ( empty($type) )
        $type = get_default_feed();
    $categories = get_the_category();
    $tags = get_the_tags(); // dòng này
    $the_list = '';
    $cat_names = array();
    $filter = 'rss';
    if ( 'atom' == $type )
        $filter = 'raw';
    if ( !empty($categories) ) foreach ( (array) $categories as $category ) {
        $cat_names[] = sanitize_term_field('name', $category->name, $category->term_id, 'category', $filter);
    }
    if ( !empty($tags) ) foreach ( (array) $tags as $tag ) { // dòng này
        $cat_names[] = sanitize_term_field('name', $tag->name, $tag->term_id, 'post_tag', $filter);
    }
    $cat_names = array_unique($cat_names);
    foreach ( $cat_names as $cat_name ) {
        if ( 'rdf' == $type )
            $the_list .= "\t\t<dc:subject><![CDATA[$cat_name]]></dc:subject>\n";
        elseif ( 'atom' == $type )
            $the_list .= sprintf( '<category scheme="%1$s" term="%2$s" />', esc_attr( apply_filters( 'get_bloginfo_rss', get_bloginfo( 'url' ) ) ), esc_attr( $cat_name ) );
        else
            $the_list .= "\t\t<category><![CDATA[" . @html_entity_decode( $cat_name, ENT_COMPAT, get_option('blog_charset') ) . "]]></category>\n";
    }
    return apply_filters('the_category_rss', $the_list, $type);
}

