Tôi đã cài đặt plugin "Sticky Custom Post Types" và thêm đoạn mã này vào file `functions.php`:

```php
function wpb_cpt_sticky_at_top( $posts ) {
    // Áp dụng chỉ cho trang lưu trữ (archive)
    if ( is_main_query() && is_post_type_archive() ) {
        global $wp_query;
        $sticky_posts = get_option( 'sticky_posts' );
        $num_posts = count( $posts );
        $sticky_offset = 0;

        // Tìm các bài viết được ghim
        for ($i = 0; $i < $num_posts; $i++) {
            // Đưa các bài viết được ghim lên đầu danh sách bài viết
            if ( in_array( $posts[$i]->ID, $sticky_posts ) ) {
                $sticky_post = $posts[$i];
                // Xóa bài viết được ghim khỏi vị trí hiện tại
                array_splice( $posts, $i, 1 );
                // Chuyển bài viết được ghim lên đầu danh sách
                array_splice( $posts, $sticky_offset, 0, array($sticky_post) );
                $sticky_offset++;
                // Xóa bài viết khỏi danh sách bài viết được ghim
                $offset = array_search($sticky_post->ID, $sticky_posts);
                unset( $sticky_posts[$offset] );
            }
        }

        // Tìm thêm các bài viết được ghim nếu cần thiết
        if ( !empty( $sticky_posts) ) {
            $stickies = get_posts( array(
                'post__in' => $sticky_posts,
                'post_type' => $wp_query->query_vars['post_type'],
                'post_status' => 'publish',
                'nopaging' => true
            ) );
            foreach ( $stickies as $sticky_post ) {
                array_splice( $posts, $sticky_offset, 0, array( $sticky_post ) );
                $sticky_offset++;
            }
        }
    }

    return $posts;
}

add_filter( 'the_posts', 'wpb_cpt_sticky_at_top' );

// Thêm lớp CSS cho bài viết được ghim để tạo kiểu khác nhau
function cpt_sticky_class($classes) {
    if ( is_sticky() ) :
        $classes[] = 'sticky';
    endif;
    return $classes;
}

add_filter('post_class', 'cpt_sticky_class');
```

