WordPress rõ ràng lưu trữ thông tin định dạng bài viết bên ngoài đối tượng $post. Trong trường hợp 'publish_post' thì điều này không phải là vấn đề vì bạn có thể kiểm tra định dạng thông qua 'get_post_format( $post->ID )' bên ngoài vòng lặp. Điều này dường như không hoạt động trong trường hợp 'xmlrpc_publish_post' hoặc 'app_publish_post'. Mọi người phải tìm cách khắc phục để các chức năng plugin/theme hoạt động trên ứng dụng di động/máy tính để bàn. Mã cụ thể của tôi được liệt kê bên dưới trong trường hợp nó là lỗi ở phía tôi.

function posse_twitter( $post_ID ) {
    error_log('Executing posse_twitter()');
    global $post;

    // kiểm tra định dạng bài viết nếu cần thiết
    if ( get_post_format( $post->ID ) != 'status' ) return;

    error_log('posse_twitter() vượt qua kiểm tra định dạng');

    $post_id = $post->ID;
    $shortlink = wp_get_shortlink();
    $tweet_content = $post->post_content.' '.$shortlink;

    // ...chạy mã một lần
    if ( !get_post_meta( $post_id, 'tweeted', $single = true ) ) {
        error_log('posse_twitter() chưa được tweet trước đó');

        // yêu cầu các thư viện liên quan
        require get_template_directory() .'/inc/posse/libraries/tmhOAuth/tmhOAuth.php';
        require get_template_directory() .'/inc/posse/libraries/tmhOAuth/tmhUtilities.php';

        $tmhOAuth = new tmhOAuth(array(
            'consumer_key'    => 'XXXXX',
            'consumer_secret' => 'XXXXX',
            'user_token'      => 'XXXXX',
            'user_secret'     => 'XXXXX',
        ));

        $code = $tmhOAuth->request('POST', $tmhOAuth->url('1/statuses/update'), array(
            'status' => $tweet_content
        ));

        error_log('posse_twitter() vượt qua tmhOAuth, nên đang ở Twitter ngay bây giờ');

        update_post_meta( $post_id, 'tweeted', true );
    }
}

add_action( 'xmlrpc_publish_post', 'posse_twitter' );
add_action( 'app_publish_post', 'posse_twitter' );
add_action( 'publish_post', 'posse_twitter' );

Tôi đã thêm 'error_log()' vì tôi đã gỡ lỗi mã này. Nó được kích hoạt khi 'xmlrpc_publish_post' và 'app_publish_post' được gọi, nhưng nó không vượt qua kiểm tra định dạng. Cập nhật: Thậm chí mã này cũng không hoạt động ngay cả khi tôi lưu bài viết dưới dạng bản nháp trước đó (qua XML-RPC).

