1. Lấy hình ảnh từ nội dung bài viết và xóa nó (nó được lưu trữ trên một trang web khác)
2. Tải lên thư mục tải lên
3. Thêm nó vào thư viện phương tiện truyền thông và
4. Cuối cùng trả về nội dung với hình ảnh được lưu trên máy chủ. Tôi không thể thực hiện bước thứ ba.

Vấn đề là với 'wp_insert_attachment', mỗi khi nó được chạy bên trong một hàm được gọi bởi 'add_filter', hoặc Apache trả về "Lỗi PHP nghiêm trọng: Kích thước bộ nhớ được phép" (giới hạn bộ nhớ PHP của tôi là 124MB) hoặc trang tiếp tục tải mãi mãi. Vấn đề tương tự không xảy ra khi 'wp_insert_attachment' chạy bên ngoài một hàm được gọi bởi 'add_filter'. Tôi không thể đặt nó bên ngoài vì tôi muốn cho nó dữ liệu $image_path nhận được từ hàm download_image. Tôi cũng đã thử gọi một hàm riêng biệt thực hiện bước 3, chạy từ bên trong hàm download_image, với $image_path được truyền như một biến nhưng vấn đề tương tự vẫn xảy ra. Tại sao điều đó xảy ra, bạn có ý tưởng nào để giải quyết nó không?

add_filter('content_save_pre', 'download_image');

function download_image($content_save_pre)
{
preg_match('/<img[^<]+>/i', $content_save_pre, $result); // Tìm hình ảnh đầu tiên với thẻ
$image_tags = $result[0]; // Lưu hình ảnh với thẻ
$content_save_pre = str_replace($image_tags, '', $content_save_pre); // Xóa hình ảnh với thẻ
preg_match('/http[^"]+/i', $result[0], $result); // Tìm URL
$url_only = $result[0];
preg_match('/[^\/]+$/i', $result[0], $result); // Tìm tên tệp
$filename = $result[0];
$uploads = wp_upload_dir(); // Tìm đường dẫn thư mục tải lên
$uploads_path = $uploads['path'];
$uploads_url = $uploads['url'];
$image = file_get_contents($url_only); // Lưu hình ảnh trong thư mục tải lên
file_put_contents($uploads_path . '/' . $filename, $image);
$image_url = $uploads_url . '/' . $filename; // URL của hình ảnh trên đĩa
$image_path = $uploads_path . '/' . $filename; // Đường dẫn của hình ảnh trên đĩa
// Thêm hình ảnh vào thư viện phương tiện - Bước 3
$wp_filetype = wp_check_filetype(basename($image_path), null);
$attachment = array(
'post_mime_type' => $wp_filetype['type'],
'post_title' => preg_replace('/\.[^.]+$/', '', basename($image_path)),
'post_content' => '',
'post_status' => 'inherit'
);
$attach_id = wp_insert_attachment($attachment, $image_path);
require_once(ABSPATH . 'wp-admin/includes/image.php');
$attach_data = wp_generate_attachment_metadata($attach_id, $image_path);
wp_update_attachment_metadata($attach_id, $attach_data);
return '<img src="' . $image_url . '"/>' . $content_save_pre; // Trả về nội dung với hình ảnh được lưu trên máy chủ
}

