Tôi có một plugin cần phải kiểm tra bản cập nhật. Hàm bên dưới - get_version_to_update được kích hoạt khi ai đó truy cập trang quản trị của plugin. Về lý thuyết sau khi yêu cầu được thực hiện, dữ liệu nên được lưu trữ trong bộ nhớ đệm thông qua transients trong 24 tiếng. Và nó hoạt động tốt cho hầu hết các trang web, nhưng đối với một số trang web cụ thể tôi nhận được dữ liệu rằng wp_remote_request được kích hoạt liên tục, điều này (theo suy nghĩ của tôi) có nghĩa là transient không được lưu trữ. Tại sao chuyện này có thể xảy ra? Có cách nào đáng tin cậy hơn để kiểm tra điều này không?

public function get_version_to_update(){      // Tôi lấy dữ liệu từ transient      $data = get_transient("my_plugin_remote_version");      // Tôi kiểm tra xem nó có tồn tại không      if($data === false){       // Ở đây tôi lấy dữ liệu từ server bằng wp_remote_request, server trả về chỉ số phiên bản, ví dụ như "2.0"         $data = wp_remote_request(...);        // Tôi lưu nó trong bộ nhớ đệm trong 24 tiếng       set_transient("my_plugin_remote_version", $data, 60 * 60 * 24);     }      // Tôi kiểm tra xem dữ liệu trả về từ server có đúng không      if ( !$data || is_wp_error( $data ) || 200 != $data['response']['code']) {        return false;      } else {        if( version_compare(MY_PLUGIN_VERSION, $new_version, '<') ) {            // trả về phiên bản mới, nếu nó mới hơn phiên bản hiện tại           return $data['body'];        } else {          return false;        }      }    }

Vấn đề này đang khiến tôi đau đầu, cảm ơn bạn vì bất cứ sự giúp đỡ nào!

