Một điều mà tôi đã gặp khó khăn là cấu trúc plugin thành nhiều file sử dụng các lớp. Mã nguồn của file plugin chính là:

<?php
/**
* Plugin Name: Tên plugin
* Plugin URI: http://someurl.com
* Mô tả: Một số mô tả
* Phiên bản: 1.0
* Tác giả: Tôi
* Author URI: http://someurl.com
*/
define( 'SBP_DIR', plugin_dir_path( __FILE__ ) );
// Định nghĩa đường dẫn thư mục plugin.
/*----------------------------------------------
* Bao gồm các file
-----------------------------------------------*/
include(SBP_DIR . 'inc/core.php');
// Hàm chính của plugin
include(SBP_DIR . 'inc/plugin-settings.php');
// HTML trang tùy chọn của plugin
/*----------------------------------------------
* Lớp Dummy_Class
-----------------------------------------------*/
global $sbp_class;
if ( !class_exists("Dummy_Class") ) {
class Dumy_Class {
/*----------------------------------------------
* Hàm Construct
-----------------------------------------------*/
function __construct() {
$this->path = plugin_basename(__FILE__);
add_action( 'init', array( $this, 'init' ) );
add_action('admin_enqueue_scripts',  array( $this, 'enqueue' ) );
add_filter("plugin_action_links_$this->path", array( $this, 'sbp_settings_link' ) );
}
/*----------------------------------------------
* Hàm init
-----------------------------------------------*/
function init() {
load_plugin_textdomain( 'sb-pack', false, basename( dirname( __FILE__ ) ) . '/lang' ); // tải miền văn bản của plugin
}
/*----------------------------------------------
* Kiểu CSS của trang tùy chọn plugin
-----------------------------------------------*/
function enqueue($hook) {
global $sbp_settings_page;
if ( $hook != $sbp_settings_page ) // chỉ tải bảng phong cách trên trang tùy chọn plugin
return;
wp_enqueue_style('styles', plugin_dir_url( __FILE__ ) . 'css/styles.css');
}
/*----------------------------------------------
* Thêm liên kết cài đặt trên trang plugin
-----------------------------------------------*/
function sbp_settings_link($links) {
$settings_link = '<a href="options-general.php?page=sbp-options">Cài đặt</a>';
array_unshift($links, $settings_link);
return $links;
}
}
//Kết thúc lớp Dummy_Class
$sb_pack = new Dummy_Class; // Khởi tạo lớp plugin
}
//Kết thúc if (!class_exists("Dummy_Class"))

