Tôi đang tải plugin Contact Form bằng yêu cầu Ajax. Nó được tải đúng, nhưng khi cố gắng gửi biểu mẫu, tôi nhận được một trang trống với phản hồi duy nhất là 0. Tôi đoán nó có liên quan đến xử lý sự kiện, nhưng không biết cách giải quyết nó. Có ý tưởng nào không? Đây là mã Ajax của tôi trong "functions.php" (ở đây tôi bỏ qua cuộc gọi mẫu trang liên hệ trong callback Ajax, vì nó hoạt động):

```php
function theme_name_scripts() {
    wp_enqueue_script( 'mi-script-ajax',get_bloginfo('stylesheet_directory') . '/js/ajax-search.js', array( 'jquery' ) );
    wp_localize_script( 'mi-script-ajax', 'MyAjax', array( 'url' => admin_url( 'admin-ajax.php' ) ) );
}

function ajax_callback() {
    //Submenu
    echo '<div id="submenu">';
    if( $sPostType !== '' ) {
        if( $sPostType == -1 ) {
            $allCategories = get_categories();
            foreach( $allCategories as $cat ) {
                echo '<li class="type-category"><a href="' . get_permalink( $cat->cat_ID ) . '">' . $cat->name . '</a></li>';
            }
        } else {
            global $wpdb;
            // set the target relationship here
            $post_type = $sPostType;
            $taxonomy = 'category';
            $terms_ids = $wpdb->get_col( $wpdb->prepare( "
                SELECT
                    tt.term_id
                FROM
                    {$wpdb->term_relationships} tr,
                    {$wpdb->term_taxonomy} tt,
                    {$wpdb->posts} p
                WHERE 1=1
                    AND tr.object_id = p.id
                    AND p.post_type = '%s'
                    AND p.post_status = 'publish'
                    AND tr.term_taxonomy_id = tt.term_taxonomy_id
                    AND tt.taxonomy ='%s'
