Với trang web của tôi, tôi làm việc với danh mục của riêng mình. Và tôi muốn rằng hệ thống phân loại được tích hợp với liên kết vĩnh viễn. Vì vậy nếu một trang tin tức có một hệ thống phân loại, liên kết vĩnh viễn sẽ thay đổi. Như thế này: mysite.com/%custom_tax%/blog/%postname% Và nếu đó là một trang: mysite.com/%custom_tax%/%postname% Nhưng nếu không có hệ thống phân loại tôi muốn: mysite.com/blog/%postname% Và nếu đó là một trang: mysite.com/%postname% Làm thế nào tôi có thể dễ dàng thực hiện điều này? Tôi đã thiết lập %custom_tax%:

add_filter('post_link', 'custom_tax_permalink', 10, 3);

add_filter('post_type_link', 'custom_tax_permalink', 10, 3);

function custom_tax_permalink($permalink, $post_id, $leavename) {

if (strpos($permalink, '%custom_tax%') === FALSE) return $permalink;

// Get post

$post = get_post($post_id);

if (!$post) return $permalink;

// Get taxonomy terms

$terms = wp_get_object_terms($post->ID, 'custom_tax');

if (!is_wp_error($terms) && !empty($terms) && is_object($terms[0])) $taxonomy_slug = $terms[0]->slug;

else $taxonomy_slug = '';

flush_rewrite_rules();

return str_replace('%custom_tax%', $taxonomy_slug, $permalink);

}

