/* Sắp xếp bài viết trong wp_list_table theo cột tăng dần hoặc giảm dần */

function custom_post_order($query){
global $prefix;

/* Thiết lập loại bài viết
_builtin => true trả về các loại bài viết mặc định của WordPress
_builtin => false trả về các loại bài viết tùy chỉnh đã đăng ký */

$post_types = get_post_types(array('_builtin' => false), 'names');

/* Loại bài viết hiện tại */

$post_type = $query->get('post_type');

/* Kiểm tra loại bài viết */

if(in_array($post_type, $post_types) && $post_type == 'gigs'){

/* Cột bài viết: ví dụ tiêu đề */

if($query->get('orderby') == ''){
$query->set('orderby', 'meta_value');
}

if($query->get('meta_key') == ''){
$query->set('meta_key',  $prefix . 'startdatetime');
}
}
}

if(is_admin()){
add_action('pre_get_posts', 'custom_post_order');
}

