Tôi cũng có hàm sau kiểm tra cho `?html` trong URL và chuyển sang mẫu trang đơn của tôi.

// Sử dụng mẫu HTML cho các bài viết nếu tham số URL được thiết lập

function html_docs_template_redirect( $template ) {
    if( isset( $_GET['html'] ) ) {
        $new_template = locate_template( array( 'html-docs.php' ) );
        if ( '' != $new_template ) {
            return $new_template ;
        }
    }
    return $template;
}

