function program_options_save( $post_id ){
if( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) return $post_id;
if ( ! current_user_can( 'edit_post', $post_id ) )
return $post_id;

if( isset( $_POST['orario'] ) )
update_post_meta( $post_id, 'orario', wp_kses( $_POST['orario'], $allowed )  );

if( isset( $_POST['giorno'] ) )
update_post_meta( $post_id, 'giorno', esc_attr( $_POST['giorno'] ) );

// This is purely my personal preference for saving check-boxes
$chk = isset( $_POST['replica'] ) && $_POST['replica'] ? 'on' : 'off';
