Tôi đang tạo một cổng thông tin cho khách hàng để họ có thể quản lý dự án và gửi phản hồi trên WordPress. Tôi có hai loại bài viết tùy chỉnh được gọi là "Khách hàng" và "Dự án", và chúng lấy thông tin từ nhau ở phía sau. Khi tôi tạo một khách hàng, nó tự động tạo ra ID bài viết của nó trong một menu thả xuống trên loại bài viết dự án, nơi tôi có thể gán một khách hàng cho một dự án. Điều tôi muốn thực hiện là hiển thị tất cả các dự án liên quan đến khách hàng đã chọn trên một trang duy nhất ở phía trước. Trang duy nhất sẽ là cổng thông tin khách hàng, được tạo ra từ loại bài viết khách hàng. Tôi không thể hiển thị bài viết liên quan. Đây là mã của tôi cho `single.php` mà sẽ hiển thị các dự án trên cổng thông tin khách hàng.

<?php
$paged = (get_query_var('paged')) ? get_query_var('paged') : 1;
$loop = new WP_Query( array(
'post_type' => array( 'projects'),
'posts_per_page' => -1,
'paged' => $paged,
'meta_query' => array(
array(
'key' => 'a_client', // tên trường tùy chỉnh
'value' => '" . get_the_ID() . "',
'compare' => 'LIKE'
)
)
));
?>

Dưới đây là mã tôi đang sử dụng để gán một khách hàng cho một dự án trong bảng điều khiển quản trị dự án. Mã này hiển thị bất kỳ khách hàng nào tôi tạo trong trang khách hàng và hiển thị tên của họ trong một menu thả xuống.

add_action( 'add_meta_boxes', 'add_clients_custom_metabox' );
function add_clients_custom_metabox() {
add_meta_box( 'custom-metabox', __( 'Clients' ), 'clients_custom_metabox', 'projects', 'side', 'high' );
}

function clients_custom_metabox($post) {
global $post,$current_user;
// ghi nhớ đối tượng $post hiện tại
$real_post = $post;
// nhận thông tin người dùng hiện tại (chúng tôi cần ID)
get_currentuserinfo();
// tạo nonce
echo '<input type="hidden" name="clients_meta_box_nonce" value="',
wp_create_nonce(basename(__FILE__)), '" />';
// nhận siêu dữ liệu đã lưu
$selected = get_post_meta( $post->ID, 'a_clients', true );
// tạo một truy vấn cho tất cả bài viết của khách hàng của người dùng
$clients_query = new WP_Query();
$clients_query->query(array(
'post_type' => 'client_portal',
'posts_per_page' => -1,
'author' => $current_user->ID
));
if ($clients_query->have_posts()){
echo '<select name="a_clients" id="a_clients">';
// lặp qua tất cả bài viết và thêm chúng vào menu thả xuống
echo '<option>Assign a client</option>';
while ($clients_query->have_posts()){
$clients_query->the_post();
echo '<option value="'.$post->ID.'" ';
if ( $post->ID == $selected){
echo 'selected="selected"';
}
echo '>'.$post->post_title .'</option>';
}
echo '<select>';
}
// đặt lại truy vấn và $post về giá trị thực
wp_reset_query();
$post = $real_post;
}
// móc để lưu siêu dữ liệu bài viết
add_action( 'save_post', 'save_clients_custom_metabox' );
// Xử lý các trường siêu dữ liệu tùy chỉnh
function save_clients_custom_metabox( $post_id ) {
global $post;
// xác minh nonce
if (!wp_verify_nonce($_POST['clients_meta_box_nonce'], basename(__FILE__))) {
return $post_id;
}
// kiểm tra tự động lưu
if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
return $post_id;
}
// kiểm tra quyền
if ('events' == $_POST['post_type']) {
if (!current_user_can('edit_page', $post_id)) {
return $post_id;
}
} elseif (!current_user_can('edit_post', $post_id)) {
return $post_id;
}
if( $_POST ) {
$old = get_post_meta($post_id, 'a_clients', true);
$new = $_POST['a_clients'];
if ($new && $new != $old){
update_post_meta($post_id, 'a_clients', $new);
}
}
}

